"""Read browser configuration; persist only exact benchmark scope and category booleans."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from pathlib import Path
import json
import re
import subprocess

BASE = Path(__file__).resolve().parent
CLOUD = BASE.parents[2] / 'hermes-lab' / 'home' / '.clanker-cloud'
PROJECT = 'ofp3osdo37cq0d0wuohxb3oj'
TEAM = 'T0C6J1XCDE0'
TESTERS = {'yyovil': 'U0C6M6DMWAW', 'tanishq': 'U0C688SF7DZ'}
CATEGORIES = ('captcha','connection','console','control','interaction','network','page','platform','screenshot','system')
EXPECTED = {'connection','system','captcha'}
SID = re.compile(r'^[a-z0-9]{8,80}$')

def read_json(path):
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError):
        return None

# Replay ledgers are locally owned attribution evidence. Do not retain segment metadata.
scopes = {}
for path in (CLOUD / 'benchmark-capture').glob('*.json'):
    record = read_json(path) or {}
    scope = record.get('scope', {})
    if isinstance(scope, dict) and scope.get('team') == TEAM and SID.fullmatch(str(scope.get('session_id',''))):
        scopes[scope['session_id']] = {k: scope[k] for k in ('team','requester','channel','thread','context','session_id') if k in scope}

runs = []
requests = {}
for path in sorted(BASE.rglob('run.json')):
    run = read_json(path) or {}
    if not run.get('id') or not run.get('scenario'):
        continue
    exact_roots = {(str(r.get('channel')), str(r.get('ts'))) for r in run.get('roots',[]) if isinstance(r,dict)}
    users = {TESTERS[t] for t in run.get('testers',[]) if t in TESTERS}
    rows = []
    meta_file = path.parent / 'kernel_sessions.jsonl'
    if meta_file.exists():
        for line in meta_file.read_text().splitlines():
            try: rows.append(json.loads(line))
            except ValueError: pass
    evidence = read_json(path.parent / 'evidence' / 'kernel.json') or {}
    rows.extend(s.get('meta',{}) for s in evidence.get('sessions',[]) if isinstance(s,dict))
    accepted = {}
    for meta in rows:
        if not isinstance(meta,dict) or meta.get('match') != 'thread' or meta.get('requester') not in users:
            continue
        session_id = str(meta.get('session_id',''))
        if not SID.fullmatch(session_id):
            continue
        for thread in meta.get('threads',[]):
            if not isinstance(thread,str) or ':' not in thread: continue
            channel, ts = thread.split(':',1)
            if (channel,ts) not in exact_roots: continue
            scope = scopes.get(session_id) or {'team':TEAM,'requester':meta['requester'],'channel':channel,'thread':ts,'session_id':session_id}
            if scope.get('requester') != meta['requester'] or (scope.get('channel'),scope.get('thread')) != (channel,ts): continue
            accepted[session_id] = scope
    # Include exact replay-ledger browsers if short-lived sessions escaped QA polling.
    for session_id, scope in scopes.items():
        if scope.get('requester') in users and (scope.get('channel'),scope.get('thread')) in exact_roots:
            accepted[session_id] = scope
    for session_id,scope in accepted.items():
        requests[session_id] = scope
    runs.append({'run':run['id'],'scenario':run['scenario'],'roots':[{'channel':ch,'thread':ts} for ch,ts in sorted(exact_roots)],'session_ids':sorted(accepted),'gaps':[] if accepted else ['No exact benchmark browser was recorded for this run.']})

def confirm(session_id):
    result = {'session_id':session_id,'scope':requests[session_id],'source':'exact_server_get_include_deleted'}
    try:
        process = subprocess.run(['kernel','browsers','get',session_id,'--include-deleted','--project',PROJECT,'--output','json'], capture_output=True, text=True, timeout=45)
        if process.returncode:
            raise ValueError('Browser configuration unavailable')
        # Raw stdout may contain capabilities. It remains in memory and is never printed or saved.
        browser = json.loads(process.stdout)
        if not isinstance(browser,dict) or browser.get('session_id') != session_id:
            raise ValueError('Browser identity unavailable')
        telemetry = browser.get('telemetry') or {}
        selected = telemetry.get('browser') or {}
        if not isinstance(selected,dict): raise ValueError('Telemetry categories unavailable')
        categories = {name: (selected.get(name,{}).get('enabled') is True if isinstance(selected.get(name),dict) else selected.get(name) is True) for name in CATEGORIES}
        result.update(categories=categories,confirmed={k for k,v in categories.items() if v} == EXPECTED,deleted=browser.get('deleted_at') is not None,checked_at_utc=datetime.now(timezone.utc).isoformat())
        if not result['confirmed']: result['gap']='Returned category configuration differs from the benchmark operational selection.'
    except (subprocess.TimeoutExpired, OSError, ValueError, TypeError):
        result.update(confirmed=False,gap='Exact browser configuration could not be safely confirmed.',checked_at_utc=datetime.now(timezone.utc).isoformat())
    return result

browsers = []
with ThreadPoolExecutor(max_workers=3) as pool:
    future_to_id = {pool.submit(confirm, sid):sid for sid in requests}
    for future in as_completed(future_to_id):
        result=future.result();browsers.append(result)
        print(json.dumps({'session_id':result['session_id'],'confirmed':result['confirmed']},separators=(',',':')),flush=True)
output={'generated_at_utc':datetime.now(timezone.utc).isoformat(),'source':'Exact QA causal-thread or protected replay-ledger scope; exact server browser GET including deleted browsers. No raw telemetry events or capability URLs retained.','expected_categories':{name:name in EXPECTED for name in CATEGORIES},'runs':runs,'browsers':sorted(browsers,key=lambda r:r['session_id'])}
target=BASE/'telemetry-evidence.json';target.write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n');target.chmod(0o600)
print(json.dumps({'path':str(target),'runs':len(runs),'browsers':len(browsers),'confirmed':sum(r['confirmed'] for r in browsers)}),flush=True)
PY
python3 .local/clanker-qa/batches/2026-10-12-replays/collect_telemetry_confirmation.py",yield_time_ms:1000,max_output_tokens:1500}));

